// 青石镇：地图沿用第一章，每章换人
function wTown(pts, extra) {
  const T = WMAPS[1].scenes.town; let rows = T.rows;
  if (extra && extra.mods) { rows = rows.map(r => r.split('')); for (const [x, y, c] of extra.mods) rows[y][x] = c; rows = rows.map(r => r.join('')); }
  if (!pts.b) pts.b = { t: 'board', n: "Bảng thông báo" };
  const o = Object.assign({ n: "Trấn Thanh Thạch", kind: 'town', theme: 'town', lit: true, lv: 1, rows, labels: T.labels, pts }, extra || {}); delete o.mods; return o;
}
