// 冰钓：钓上来的鱼，冰大娘要三条
W_MINI_RW.fish = (ch, win) => { if (ch !== 6 || !win) return ''; const S = wstate(6); S.pz.fish = (S.pz.fish || 0) + 1;
  const q = S.side.S10, need = q && q.st === 'on' && q.step === 0;
  if (Math.random() < 0.15) { const key = gemKey(RNG.pick(Object.keys(GEM_TYPES)), 1); addGem(key); return `Mổ bụng cá ra — bên trong có một viên ${gemName(key)}!` + (need ? `(Cá băng ${Math.min(3, S.pz.fish)}/3)` : ''); }
  if (need) return S.pz.fish >= 3 ? "Ba con cá băng, đủ rồi. Mang cho bà Băng." : `Cá băng ${S.pz.fish}/3`;
  SAVE.gold += 25; return "Mang cá vào làng đổi được hai mươi lăm lượng bạc."; };
// 打雪仗：赢了冰小雪，她就把秘密告诉你
W_MINI_RW.snowball = (ch, win) => { if (ch !== 6 || !win) return ''; const S = wstate(6);
  if (S.side.S9 && S.side.S9.st === 'on' && !S.flags.snowWin) { S.flags.snowWin = 1; return "Băng Tiểu Tuyết quệt tuyết trên mặt: “…Coi như anh giỏi! Lại đây, nói cho anh một bí mật.”"; }
  SAVE.gold += 30; return "Lũ trẻ góp được ba mươi lượng bạc vụn “cống nạp”, xin bạn mai lại tới."; };
// 寒气：雪山道和雪原上，离火堆远了就一点点冻透；冻透了每走几步掉血
const g6ColdRate = (run) => (wkeys().xuexue ? 0.5 : 1) * (wkeys().huotan ? 0.6 : 1) * (run.food === 'yutang' ? 0.5 : 1);
const g6NearFire = (m, x, y) => Object.keys(m.pts).some(c => m.def.pts[c].t === 'camp' && m.pts[c].some(p => Math.abs(p.x - x) + Math.abs(p.y - y) <= 3));
const g6Now = () => typeof performance !== 'undefined' ? performance.now() : 0;
