        1: { t: 'clue', grp: 'hunqian', n: "Thẻ hồn · Trương Nhị", when: g7Day, lines: [['narr', "Trời sáng rồi. Các sạp đều dọn cả, con phố dài vắng tanh, chỉ còn đầy đất giấy tiền."], ['narr', "Trên tường phía tây treo đầy thẻ gỗ, thẻ này sát thẻ kia, mỗi thẻ ghi một cái tên."], ['narr', "“Trương Nhị. Bán hàng rong. Dương thọ chưa tận. Người mượn hồn: Bạch.”"], ['zhen', "…Trương Nhị. Người bán kim chỉ đầu đông trấn. Mất tích hai năm trước."]] },
        2: { t: 'clue', grp: 'hunqian', n: "Một hàng thẻ hồn", when: g7Day, lines: [['narr', "“Lý tú tài. Dương thọ chưa tận. Người mượn hồn: Bạch.”"], ['narr', "“Quả phụ họ Tôn. Dương thọ chưa tận. Người mượn hồn: Bạch.”"], ['narr', "Một thẻ, hai thẻ, ba thẻ… mười một thẻ. Mười một cái tên."], ['narr', "Người mượn hồn, đều cùng một chữ."], ['zhen', "…Bạch."]] },
