        m: { t: 'sign', n: "Quy củ chợ ma", lines: [['narr', "“Quy củ chợ ma: Một, người sống vào chợ phải có giấy thông hành. Hai, lấy vật đổi vật, lấy ký ức đổi ký ức. Ba, trời sáng dọn hàng, không bán chịu.”"], ['narr', "“Bốn, có ai gọi tên ngươi, đừng thưa.”"]] },
