      steps: [{ d: "Kể chuyện Vương Tiểu Lục với sư phụ Lưu", goal: { talk: 'liu' }, lines: [['liu', "Trên thực tế…"], ['narr', "Sư phụ Lưu lục trong tủ ra một tấm thẻ gỗ, thổi bụi, cầm bút viết ba chữ: “Vương Tiểu Lục”."], ['narr', "Chữ viết ngay ngắn đàng hoàng."], ['liu', "Ba mươi năm trước, ta ghi sót một cái tên, cứu một con ma."], ['liu', "Hôm nay ta ghi thêm một cái tên. Cũng coi như… trả xong."], ['narr', "Ông đặt bài vị lên tầng giá cao nhất trong nhà quàn, thắp một nén hương."]] }],
