// ==================== 第八章 · 白云观（主题：怕死）  + 幕间四 · 出征前夜 ====================
// 主线：珍姑娘的地图 → 刘师傅的道籍 → 龙道长三十年前摔的那支笔 → 康福贵的送菜车 → 铁蛋的钥匙 → 山脚茶棚
