  sanding:  { n: "Đinh đã đoạt lại", d: "Ba cây đinh Mộc, Kim, Hỏa đều nằm trong tay bạn. Trận tứ đinh của Bạch Vân Tử, một trận nhãn cũng không bày nổi.", spr: 'key' },
  luyin:    { n: "Giấy thông hành người sống vào âm phủ", d: "Sư phụ Lưu cấp. Về nguyên tắc, con dấu này ở âm phủ chưa chắc đã dùng được.", spr: 'scroll' },
