        g: { t: 'clue', grp: 'gaoshi', n: "Thông báo trên tường", lines: [
          ['narr', "Trên tường thiên điện dán một tờ hoàng bảng, viết bằng chu sa:"],
          ['narr', "“Đêm nay bổn quán lập đàn, dâng đồng nam đồng nữ mỗi loại một…”"],
          ['narr', "Chữ phía sau bị ai đó dùng máu gạch đi. Máu đã khô, ngả đen."],
          ['narr', "Bên cạnh viết thêm một dòng xiêu vẹo, cũng bằng máu:"],
          ['narr', "“Dâng một thiên hồ.”"]] },
        h: { t: 'clue', grp: 'xianghuo', n: "Sổ nhang đèn ở thiên điện", lines: [['narr', "Dưới hương án đè quyển sổ nhang đèn thứ hai, cũ hơn quyển ở tiền điện nhiều, giấy đã giòn cả."], ['narr', "“Năm… tháng…, họ Vương trấn Thanh Thạch, hương một nén, thọ năm năm.”"], ['narr', "“Năm… tháng…, họ Triệu trấn Thanh Thạch, hương một nén, thọ năm năm.”"], ['narr', "Lật từng trang từng trang, những dòng họ của trấn Thanh Thạch ba trăm năm qua, đều có trong đó."]] },
