        q: { t: 'qspot', id: 'danlu', n: "Lò đan lớn nhất" },
        1: { t: 'clue', grp: 'rendan', n: "Lò đan", lines: [['narr', "Một lò đan cao hơn đầu người, trong lò không đốt củi, mà đốt từng bó giấy bùa."], ['narr', "Trên khay gỗ bên lò xếp một hàng viên thuốc, mỗi viên đều khắc tên một người."], ['narr', "“Tôn Thất” “Lý Tứ” “Tú Liên”…"], ['narr', "Đều là người trong trấn."]] },
        2: { t: 'clue', grp: 'rendan', n: "Đơn luyện đan", lines: [['narr', "Trên tường dán một đơn luyện đan, chữ viết cực kỳ ngay ngắn:"], ['narr', "“Nhân đan một lò, lấy chín mươi chín luồng dương khí người sống. Uống vào, có thể kéo dài tuổi thọ một giáp.”"], ['narr', "Bên dưới một dòng chữ nhỏ: “Lò thứ ba trăm lẻ hai.”"], ['zhen', "Ba trăm lẻ hai lò."], ['zhen', "Một lò chín mươi chín người."], ['narr', "Cô Trân không tính tiếp nữa."]] },
        F: { t: 'elite', id: 'kuileiwang', name: "Vua khôi lỗi lò đan", mon: 2, lv: 30, tag: 'tj8', big: 1, abs: [{ t: 'shell', every: 4, pct: 0.12, say: "…Đan… hỏa…" }, { t: 'roar', every: 3, say: "Ầm —" }] },
        w: { t: 'sign', n: "Sổ xuất đan", lines: [['narr', "Một quyển sổ xuất đan: năm… tháng…, ra mấy viên đan, gửi đi đâu."], ['narr', "Viên nào cũng gửi đến cùng một nơi: “Kinh các · Sư tôn”."], ['narr', "Khoản gần nhất còn chưa viết xong: “Hồ, một. Đợi mở lò.”"]] },
        y: { t: 'sign', n: "Quy tắc đan phòng", lines: [['narr', "“Quy tắc đan phòng: Một, lửa lò không tắt. Hai, dẫn thuốc không thiếu. Ba, tiếng khóc không đếm xỉa.”"]] },
