        v: g8Xt('xt8i', "Thím Lưu cạnh tiệm thuốc", [['narr', "Thím Lưu nhìn rõ mặt bạn, “ối chà” kêu lên một tiếng."], ['narr', "“A Thổ? Chẳng phải cậu là người ở tiệm thuốc… Cô Ngoc đâu? Ngày nào cô ấy cũng càu nhàu cậu kén ăn…”"], ['narr', "Thím nói được nửa câu, thấy sắc mặt bạn, không nói tiếp nữa."]]),
