      steps: [{ d: "Cùng phán quan lật Sổ Sinh Tử", goal: { talk: 'panguan' }, lines: [['narr', "Phán quan lật Sổ Sinh Tử, ngón tay vuốt xuống từng dòng."], ['panguan', "“Khang Phúc Quý. Chưởng quỹ Túy Tiên Lâu. Dương thọ… bốn mươi chín.”"], ['me', '……'], ['panguan', "Khoan, phía sau còn chữ."], ['panguan', "“…năm nữa”."], ['panguan', "Bốn mươi chín năm nữa."], ['panguan', "Gã béo này mạng cứng lắm. Chín mươi tám tuổi, đang ăn cơm thì cười mà chết."], ['narr', "Bạn đứng dưới Vọng Hương Đài một lúc, bật cười thành tiếng."]] }],
