        if ((wflags().woke || 0) >= 7) L.push(['narr', "Tôn Thất, Lý Tứ, Tú Liên, lão Chu, Nhị Trụ, Tiểu Mã… những người được gọi tỉnh trên núi Bạch Vân Quán, không thiếu một ai, chen kín cả ba tầng lầu."]);
        else if ((wflags().woke || 0) >= 3) L.push(['narr', "Mấy người được gọi tỉnh trên núi Bạch Vân Quán cũng tới, chen ở cửa, nghển cổ nhìn vào."]);
        L.push(['liu', "E hèm. Về nguyên tắc, ta tuyên bố hai người là vợ chồng."], ['liu', "…Trên thực tế, cũng vậy."]);
        L.push(a('liu') >= 6 ? ['liu', "Người trẻ tuổi. Chuyện ba mươi năm trước ta không dám làm, cậu đã làm. Ta kính cậu một chén."] : ['liu', "Thủ tục đều xong cả rồi. Lễ thành."]);
        L.push(['kang', "Tiền mừng… trả góp được không?"]);
        L.push(a('kang') >= 6 ? ['kang', "…Thôi thôi, bữa này ta mời! Khang mỗ đời này, đáng giá nhất là quen được cậu!"] : ['kang', "…Đùa thôi! Cứ ăn thoải mái! Ta, ta giảm hai mươi phần trăm!"]);
        L.push(['zhenda', "Thịt kho tới đây — ! Bốc thêm một nắm đường!"], ['narr', "Trân Đại cầm muôi. Cô Trân đuổi theo Khang Phúc Quý đòi chân giò kho, chạy khắp phòng."]);
        L.push(a('zhen') >= 7 ? ['zhen', "…Này. Trả ta lệnh bài."] : ['zhen', "…Chúc mừng."], ['narr', "Bạn tháo lệnh bài bộ khoái xuống, đưa cho cô. Cô nhận lấy, không đeo lại lên hông, mà cất vào ngực áo."]);
        if (a('zhen') >= 7) L.push(['zhen', "Ngươi mà dám đối xử không tốt với con bé, ta chém ngươi đầu tiên."]);
        L.push(['narr', "Lôi Lão Hổ với Tiểu Hổ chơi oẳn tù tì, ai thua thì uống. Tiểu Hổ chưa uống bát nào, Lôi Lão Hổ đã say lăn dưới gầm bàn, tay vẫn nắm nửa cán cờ."]);
        L.push(['tiedan', "“Lò Rèn Số Một Thiên Hạ”! Biển hiệu em tự viết đấy!"], ['smith', "…Viết cũng tạm được."]);
        L.push(['narr', "Trên bàn tròn trống một chỗ ngồi."], ['narr', "Trên chỗ ngồi bày một bàn cờ, quân cờ không động tới quân nào, vẫn y như ván đánh dở hôm ấy. Bên cạnh bàn cờ, đặt ngọn đèn Chính Khí."],
          ['narr', "Bạch Vân Quán đổi thành “Chính Khí Thư Viện”. Trước cửa thư viện dựng một tấm bia, văn bia do bạn rập."], ['narr', "Cả đời ông rập bia cho người khác. Cuối cùng, có người rập cho ông một tấm."]);
