        if (wPast(9, 'soupYes') || wkeys().tangwan) L.push(['narr', "Giữa tiệc, một bà lão tóc bạc ló đầu ở cửa, giơ chiếc muôi gỗ trong tay về phía bạn, rồi biến mất. Trên bàn có thêm một bát canh. Vị ngọt."]);
        if (wPast(2, 'wolfSpared')) L.push(['narr', "Trong rừng ngoài trấn, vọng lại một tiếng sói tru dài. Như đang chúc mừng."]);
        if (wPast(7, 'pai7')) L.push(['narr', "Trên tầng giá cao nhất của nhà quàn, trước bài vị của Vương Tiểu Lục, có người đặt một chén rượu mừng."]);
        L.push(['ngoc', "…Tiền thuốc."], ['me', "Hửm?"], ['ngoc', "Tiền thuốc, coi như sính lễ."]);
        if (a('ngoc') >= 9) L.push(['narr', "Tiệc tan, hai người ngồi trên mái tiệm thuốc. Trăng rất tròn."], ['ngoc', "A Thổ."], ['me', "Ừ."], ['ngoc', "…Lần này, ngươi không để ta đợi lâu."]);
